; slots.asm -- chapter 3: every slot behind every page
; generated by gen03.py
        INCLUDE "msx.inc"
        OUTPUT "slots.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
PROBE_RAM EQU $C400             ; a copy of the probe, in page 3
slotreg EQU VARS + 12           ; port $A8 as the BIOS left it
slot    EQU VARS + 13
pg      EQU VARS + 14
cellp   EQU VARS + 15           ; 2 bytes: where the next result goes
cells   EQU VARS + 32           ; 16 results of 6 bytes: sum, kept, not $FF
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, probe            ; a copy that can run while pages 0-2 change
        ld de, PROBE_RAM
        ld bc, probe_end - probe
        ldir
        in a, (PPI_A)
        ld (slotreg), a
        ld hl, cells
        ld (cellp), hl
        xor a
        ld (slot), a
sloop:  xor a
        ld (pg), a
ploop:  ld a, (pg)              ; the slot register with this page's two
        ld b, a                 ; bits replaced by the slot under test
        ld a, (slot)
        ld c, %11111100         ; C: the mask, D: the slot, both moved to the page
        ld d, a
        inc b
        jr .first
.move:  rlc c
        rlc c
        sla d
        sla d
.first: djnz .move
        ld a, (slotreg)
        and c
        or d                    ; A: the value for port $A8
        ld e, a
        ld a, (pg)
        rrca
        rrca                    ; the page's first address, high byte
        ld h, a
        ld a, e
        ld l, a
        ld a, (pg)
        cp 3
        ld a, l
        jr z, .p3
        call PROBE_RAM          ; pages 0-2: the copy in page 3
        jr .got
.p3:    call probe              ; page 3: the original, in page 1
.got:   exx
        push bc                 ; the bytes that are not $FF
        exx
        push iy                 ; the bytes that kept a write
        push ix                 ; the sum
        ld hl, (cellp)
        ld b, 3
.store: pop de
        ld (hl), e
        inc hl
        ld (hl), d
        inc hl
        djnz .store
        ld (cellp), hl
        ld a, (pg)
        inc a
        ld (pg), a
        cp 4
        jr nz, ploop
        ld a, (slot)
        inc a
        ld (slot), a
        cp 4
        jr nz, sloop
; the page
        ld b, 1
        ld c, 0
        ld hl, t_head
        call puts
        ld ix, cells
        ld b, 3
        xor a
srow:   push af
        ld c, 1
        call hexdig             ; the slot
        ld e, 0                 ; the page
scell:  ld hl, cols
        ld d, 0
        add hl, de
        ld c, (hl)              ; the column of this page
        push de
        ld l, (ix+2)
        ld h, (ix+3)            ; kept
        ld a, h
        cp $40                  ; 16,384 kept: RAM
        jr nz, .notram
        ld hl, t_ram
        call puts
        inc b
        ld a, c
        sub 3
        ld c, a
        ld l, (ix+2)
        ld h, (ix+3)
        call putd16
        dec b
        jr .next
.notram:
        ld a, (ix+4)
        or (ix+5)               ; no byte other than $FF: nothing there
        jr nz, .some
        ld hl, t_none
        call puts
        jr .next
.some:  ld a, (ix+2)
        or (ix+3)
        ld hl, t_rom            ; no byte kept a write: ROM
        jr z, .rom
        ld hl, t_what
.rom:   call puts
        inc b
        ld a, c
        sub 3
        ld c, a
        ld a, (ix+1)
        call puthex             ; the sum, in hexadecimal
        ld a, (ix+0)
        call puthex
        dec b
.next:  ld de, 6
        add ix, de
        pop de
        inc e
        ld a, e
        cp 4
        jr nz, scell
        pop af
        inc b
        inc b
        inc b
        inc a
        cp 4
        jr nz, srow
        ld b, 16
        ld c, 0
        ld hl, t_a8
        call puts
        ld a, (slotreg)
        call puthex
        inc c
        ld a, (slotreg)
        call fatbits
        ld b, 17
        ld c, 10
        ld hl, t_pages
        call puts
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; probe: A = the value for port $A8, H = the first address of the page.
; Returns IX = the sum of the page's 16,384 bytes (16 bits), IY = how many
; kept a write, BC' = how many are not $FF. While the page shows the slot
; under test it uses no memory but that page and no stack, so it can test the
; page that holds the stack. Only relative jumps: it runs wherever it is put.
probe:  ld e, a                 ; E: the value under test
        in a, (PPI_A)
        ld d, a                 ; D: the value to put back
        ld l, 0
        ld ix, 0
        ld iy, 0
        exx
        ld bc, 0
        exx
        ld a, e
        out (PPI_A), a          ; the page now shows the slot under test
.byte:  ld a, (hl)
        ld c, a
        ld b, 0
        add ix, bc              ; the sum
        cp $FF
        jr z, .ff
        exx
        inc bc                  ; not $FF
        exx
.ff:    cpl
        ld (hl), a
        cp (hl)
        ld (hl), c              ; the byte put back
        jr nz, .kept
        inc iy                  ; it kept the write
.kept:  inc hl
        ld a, h
        and %00111111
        or l
        jr nz, .byte            ; until HL reaches the next page
        ld a, d
        out (PPI_A), a          ; the slots as they were
        ret
probe_end:

cols:   db 5, 12, 19, 26
t_head: db "slot $0000  $4000  $8000  $C000", 0
t_ram:  db "RAM", 0
t_rom:  db "ROM", 0
t_none: db " - ", 0
t_what: db "???", 0
t_a8:   db "port $A8: ", 0
t_pages: db "33221100 page", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret

; putd16: HL = a number (0-65535) as five characters, right-aligned.
;         B = row, C = column; C moves on by 5. Uses A, DE, HL.
putd16: push bc
        ld de, d16buf
        ld bc, -10000
        call .digit
        ld bc, -1000
        call .digit
        ld bc, -100
        call .digit
        ld bc, -10
        call .digit
        ld a, l
        add a, '0'
        ld (de), a              ; the units, always printed
        ld hl, d16buf
        ld b, 4
.blank: ld a, (hl)              ; leading zeros become spaces
        cp '0'
        jr nz, .print
        ld (hl), ' '
        inc hl
        djnz .blank
.print: pop bc
        ld hl, d16buf
        ld e, 5
.out:   ld a, (hl)
        call putc
        inc c
        inc hl
        dec e
        jr nz, .out
        ret
.digit: ld a, '0' - 1           ; how many times BC fits: subtract until it goes below
.sub:   inc a
        add hl, bc              ; BC is negative: the carry means it still fitted
        jr c, .sub
        sbc hl, bc              ; one too many: add it back (the carry is clear)
        ld (de), a
        inc de
        ret
d16buf  EQU VARS + 4            ; 5 bytes of RAM, after numbuf

; fatbits: A = a byte, drawn as 8 boxes, bit 7 first: a filled box for 1,
;          an empty one for 0. B = row, C = column; C moves on by 8.
;          Uses A. Keeps HL.
fatbits:
        push hl
        ld l, a
        ld h, 8
.bit:   ld a, 1                 ; an empty box ...
        rl l                    ; the next bit, into the carry
        jr nc, .put
        ld a, 2                 ; ... or a filled one
.put:   call putc
        inc c
        dec h
        jr nz, .bit
        pop hl
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
